import React, { useEffect, useState } from "react";
import { ArrowLeft, Menu } from "react-feather";
import { useDispatch, useSelector } from "react-redux";
import { useHistory } from "react-router-dom/cjs/react-router-dom.min";
import {
  Button,
  Card,
  CardBody,
  Col,
  Collapse,
  Modal,
  ModalBody,
  ModalFooter,
  ModalHeader,
  Row,
} from "reactstrap";
import jobOpeningMatchesActions from "../../redux/jobOpeningMatches/actions";
import { useParams } from "react-router-dom/cjs/react-router-dom";
import DataTable from "react-data-table-component";
import ComponentSpinner from "../../@core/components/spinner/Loading-spinner";
import subscriptionActions from "../../redux/subscription/actions";
import InterviewDialog from "../../components/Dialog/interviewDialog";
import interviewActions from "../../redux/interview/actions";
import candidateActions from "../../redux/candidate/actions";
import onBoardingActions from "../../redux/onBoarding/actions";
import clientActions from "../../redux/client/actions";
import { tostify, tostifyError, tostifySuccess } from "../../components/Tostify";
import { getInterviewAPI } from "../../apis/interview";
import { updateCandidateAPI } from "../../apis/candidate";
import { awsUploadAssetsWithResp } from "../../helper/awsUploadAssets";
import { allAccessEmail } from "../../constant/constant";
import Avatar from "@components/avatar";
import { MdOutlineCategory } from "react-icons/md";

/** Best Matches table only — missing / 0 salary → "-" */
const formatSalaryDisplay = (value) => {
  if (value == null || value === "") return "-";
  const n = Number(value);
  if (!Number.isNaN(n) && n === 0) return "-";
  return value;
};
import { BsPersonWorkspace } from "react-icons/bs";
import { MdOutlineWorkHistory } from "react-icons/md";
import { BsGenderAmbiguous } from "react-icons/bs";
import { MdOutlinePlace } from "react-icons/md";
import { PiStudentLight } from "react-icons/pi";
import { MdOutlineAttachMoney } from "react-icons/md";
import JobOpeningMatchFilters from "../../components/JobOpening/JobOpeningMatchFilters";
import JobMatchProfileDialog from "../../components/JobOpening/JobMatchProfileDialog";
import {
  InterviewStatusCell,
  getInterviewButtonLabel,
  getViewProfileButtonLabel,
  buildInterviewEditState,
  buildInterviewCreateState,
  buildInterviewUpdatePayload,
  fetchJobScopedInterview,
  isShortlistedInterview,
  NewBestMatchCandidateBadge,
  shouldShowNewBestMatchBadge,
} from "../../components/JobOpening/jobMatchTableHelpers";
import { markNewBestMatchSeenAPI } from "../../apis/jobOpening";

const JobOpeningMatches = ({ jobIdOverride, embeddedMode = false }) => {
  const history = useHistory();
  const dispatch = useDispatch();
  const params = useParams();
  const activeJobId = jobIdOverride || params?.id;
  const slug = localStorage.getItem("slug");
  const themeColor = useSelector(
    (state) => state?.agency?.agencyDetail?.themecolor
  );
  const user = useSelector((state) => state?.auth?.user);
  const loginUser = useSelector((state) => state?.auth?.user);
  const clientsState = useSelector((state) => state.client);
  const onboardingState = useSelector((state) => state.onBoarding);
  const clients = Array.isArray(clientsState?.results)
    ? clientsState.results
    : Array.isArray(onboardingState?.results)
      ? onboardingState.results
      : [];
  const candidates = useSelector((state) => state.candidate.results);
  const { isLoading, jobOpeningMatchCandidate, jobOpeningRow } = useSelector(
    (state) => state?.jobOpeningMatches
  );
  const { resumeCountFinishError } = useSelector(
    (state) => state?.subscription
  );

  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);
  const [sortBy, setSortBy] = useState("matchScore");
  const [matchScore, setMatchScore] = useState("");
  const [matchDuration, setMatchDuration] = useState("");
  const [interviewLoading, setInterviewLoading] = useState(false);
  const [filterToggleMode, setFilterToggleMode] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [showInterview, setShowInterview] = useState(false);
  const [interview, setInterview] = useState({});
  const [createInterview, setCreateInterview] = useState(false);
  const [updateInterview, setUpdateInterview] = useState(false);
  const [selectCandidateValidation, setSelectCandidateValidation] = useState(null);
  const [selectCompanyValidation, setSelectCompanyValidation] = useState(null);
  const [dateValidation, setDateValidation] = useState(null);
  const [interviewStartValidation, setInterviewStartValidation] = useState(null);
  const [interviewValidation, setInterviewValidation] = useState(null);
  const [showProfile, setShowProfile] = useState(false);
  const [profileCandidate, setProfileCandidate] = useState({});
  const [industriesData, setIndustriesData] = useState([]);
  const [gender, setGender] = useState("");
  const [profileEmail, setProfileEmail] = useState("");
  const [profileReadOnly, setProfileReadOnly] = useState(true);
  const [profileSaving, setProfileSaving] = useState(false);
  const [viewedCandidateIds, setViewedCandidateIds] = useState(() => new Set());
  // Local gate so first paint never shows "no records" before saga sets isLoading
  const [initialLoad, setInitialLoad] = useState(true);
  const sawLoadingRef = React.useRef(false);

  console.info("--------------------");
  console.info("jobOpeningMatchCandidate => ", jobOpeningMatchCandidate);
  console.info("jobOpeningRow => ", jobOpeningRow);
  console.info("--------------------");

  const showTableLoader = isLoading || interviewLoading || initialLoad;

  const getJobOpeningRow = async () => {
    await dispatch({
      type: jobOpeningMatchesActions.GET_JOB_OPENING_ROW,
      payload: activeJobId,
    });
  };

  const getJobOpeningMatchCandidate = async (
    pageNum,
    perPageNum,
    sort = sortBy,
    score = matchScore,
    duration = matchDuration
  ) => {
    // Sync loader before saga runs so empty table never flashes
    dispatch({
      type: jobOpeningMatchesActions.JOB_MATCHES_LOADER,
      payload: true,
    });
    await dispatch({
      type: jobOpeningMatchesActions.GET_JOB_OPENING_MATCH_CANDIDATE,
      payload: {
        id: activeJobId,
        page: pageNum,
        perPage: perPageNum,
        sortBy: sort,
        matchScore: score || undefined,
        matchDuration: duration || undefined,
      },
    });
  };

  useEffect(() => {
    if (isLoading) sawLoadingRef.current = true;
  }, [isLoading]);

  // Clear header "new best match" badge for this job after viewing
  useEffect(() => {
    if (!activeJobId) return undefined;
    markNewBestMatchSeenAPI(activeJobId).catch(() => {});
  }, [activeJobId]);

  useEffect(() => {
    const rows = jobOpeningMatchCandidate?.results;
    if (!Array.isArray(rows) || !rows.length) return;
    setViewedCandidateIds((prev) => {
      const next = new Set(prev);
      let changed = false;
      rows.forEach((row) => {
        if (row?.viewedByCurrentUser === true && row?.id) {
          const id = String(row.id);
          if (!next.has(id)) {
            next.add(id);
            changed = true;
          }
        }
      });
      return changed ? next : prev;
    });
  }, [jobOpeningMatchCandidate?.results]);

  // Drop local gate only after we actually entered a loading cycle
  useEffect(() => {
    if (initialLoad && sawLoadingRef.current && !isLoading) {
      setInitialLoad(false);
    }
  }, [initialLoad, isLoading]);

  const reloadMatches = () =>
    getJobOpeningMatchCandidate(page, perPage, sortBy, matchScore, matchDuration);

  const handleSortChange = (value) => {
    setSortBy(value);
  };

  const handleMatchScoreChange = (value) => {
    setMatchScore(value);
  };

  const handleMatchDurationChange = (value) => {
    setMatchDuration(value);
  };

  const handleFilterSearch = () => {
    setPage(1);
    getJobOpeningMatchCandidate(1, perPage, sortBy, matchScore, matchDuration);
    setFilterToggleMode(false);
  };

  const handleFilterClear = () => {
    setSortBy("matchScore");
    setMatchScore("");
    setMatchDuration("");
    setPage(1);
    getJobOpeningMatchCandidate(1, perPage, "matchScore", "", "");
    setFilterToggleMode(false);
  };

  useEffect(() => {
    (async () => {
      if (activeJobId) {
        await getJobOpeningRow();
        await getJobOpeningMatchCandidate(page, perPage);
      }
    })();
  }, [activeJobId]);

  useEffect(() => {
    if (!showInterview) return;
    (async () => {
      await dispatch({
        type: candidateActions.GET_CANDIDATE,
        payload: { page: 1, perPage: 10, filterData: {} },
      });
      // Interview company dropdown uses Clients (onBoardingId field stores client id)
      await dispatch({
        type: clientActions.GET_CLIENT,
        payload: {
          page: 1,
          perPage: 100,
          filterData: {},
        },
      });
      await dispatch({
        type: onBoardingActions.GET_ONBOARDING,
        payload: {
          filterData: {},
          userId: loginUser?.id,
          page: 1,
          perPage: 50,
        },
      });
    })();
  }, [showInterview, dispatch, loginUser?.id]);

  const openInterviewDialog = async (candidate) => {
    setInterviewLoading(true);
    const jobOpeningId = activeJobId;
    const existing = await fetchJobScopedInterview(
      getInterviewAPI,
      candidate?.id,
      jobOpeningId
    );
    if (existing?.id) {
      setInterview(
        buildInterviewEditState(
          existing,
          candidate,
          jobOpeningId,
          loginUser?.id
        )
      );
      setCreateInterview(false);
      setUpdateInterview(true);
    } else {
      setInterview(
        buildInterviewCreateState(candidate, jobOpeningId, loginUser?.id)
      );
      setSelectCompanyValidation(null);
      setCreateInterview(true);
      setUpdateInterview(false);
    }
    setShowInterview(true);
    setInterviewLoading(false);
  };

  const interviewCreateHandler = async () => {
    setInterviewLoading(true);
    const payload = {
      ...(Array.isArray(interview) ? {} : interview || {}),
      userId: interview?.userId || loginUser?.id,
      jobOpeningId: interview?.jobOpeningId || activeJobId,
    };
    await dispatch({
      type: interviewActions.CREATE_INTERVIEW,
      payload: { data: payload, page: 1, perPage: 10 },
    });
    setInterviewLoading(false);
    setShowInterview(false);
    setCreateInterview(false);
    setUpdateInterview(false);
    setInterview({});
    reloadMatches();
  };

  const interviewUpdateHandler = async () => {
    const payload = buildInterviewUpdatePayload(interview);
    if (!payload?.id) {
      tostify("Interview not found — please close and try again");
      setInterviewLoading(false);
      return;
    }
    setInterviewLoading(true);
    await dispatch({
      type: interviewActions.UPDATE_INTERVIEW,
      payload: { data: payload, page: 1, perPage: 10 },
    });
    setInterviewLoading(false);
    setShowInterview(false);
    setCreateInterview(false);
    setUpdateInterview(false);
    setInterview({});
    reloadMatches();
  };

  const interviewHandler = async () => {
    if (updateInterview) {
      interviewUpdateHandler();
      return;
    }
    if (!createInterview) return;
    if (selectCandidateValidation === null) tostify("Please Select Candidate");
    else if (selectCompanyValidation === null) tostify("Please Select Company");
    else if (
      dateValidation === null &&
      !isShortlistedInterview(interview)
    )
      tostify("Please Select date");
    else if (
      interviewStartValidation === null &&
      (interview?.interviewStatus === "scheduled" ||
        interview?.interviewStatus === undefined)
    )
      tostify("Please Select Interview Time");
    else if (
      interviewValidation === null &&
      interview?.interviewStatus === "scheduled"
    )
      tostify("Please Select Interview Option");
    else interviewCreateHandler();
  };

  const openViewProfile = (row) => {
    if (!row?.id) return;
    const candidateId = String(row.id);
    dispatch({
      type: candidateActions.CANDIDATE_STATUS,
      payload: { id: candidateId },
    });
    setViewedCandidateIds((prev) => new Set(prev).add(candidateId));
    setProfileCandidate(row);
    setIndustriesData(row?.industries_relation || []);
    setGender(row?.gender || "");
    setProfileEmail(row?.email || "");
    setProfileReadOnly(true);
    setShowProfile(true);
  };

  const openEditProfile = (row) => {
    if (!row?.id) return;
    const candidateId = String(row.id);
    const isForeignAgency =
      Boolean(row?.agency?.email) &&
      Boolean(user?.agency?.email) &&
      row.agency.email !== user.agency.email &&
      user?.email !== allAccessEmail &&
      user?.agency?.email !== allAccessEmail;

    dispatch({
      type: candidateActions.CANDIDATE_STATUS,
      payload: { id: candidateId },
    });
    setViewedCandidateIds((prev) => new Set(prev).add(candidateId));

    const normalizedMobile = String(row?.mobile || "")
      .replace(/\D/g, "")
      .slice(-10);
    const normalizedAlt = String(row?.alternateMobile || "")
      .replace(/\D/g, "")
      .slice(-10);

    setProfileCandidate({
      ...row,
      mobile: normalizedMobile,
      alternateMobile: normalizedAlt || row?.alternateMobile || "",
    });
    setIndustriesData(row?.industries_relation || []);
    setGender(row?.gender || "");
    setProfileEmail(row?.email || "");
    setProfileReadOnly(isForeignAgency);
    setShowProfile(true);
  };

  const handleProfileSave = async () => {
    if (profileReadOnly || !profileCandidate?.id) return;
    try {
      setProfileSaving(true);
      const data = { ...profileCandidate };
      delete data.interviews;

      const typeResume = typeof data?.resume;
      const typeImage = typeof data?.image;
      const awsBucket = process.env.REACT_APP_AWS_BUCKET_NAME;

      if (typeImage === "object" && data?.image !== null && awsBucket) {
        const resp = await awsUploadAssetsWithResp(data.image);
        data.image = `${resp.url}`;
      }
      if (typeResume === "object" && data?.resume !== null && awsBucket) {
        const resp = await awsUploadAssetsWithResp(data.resume);
        data.resume = `${resp.url}`;
      }

      const fm = new FormData();
      const skipUpdateKeys = new Set([
        "resumeParsedAt",
        "resumeFiles",
        "resumeParseCache",
        "interviews",
        "client",
        "agency",
        "jobCategory",
        "industries",
        "appliedStatus",
        "matchScore",
        "saved_Candidates",
        "savedCandidates",
        "_id",
        "latestInterview",
        "viewedByCurrentUser",
        "profileCompleteness",
      ]);
      const mobileDigits = String(data?.mobile || "")
        .replace(/\D/g, "")
        .slice(-10);
      const altDigits = String(data?.alternateMobile || "")
        .replace(/\D/g, "")
        .slice(-10);

      fm.append("id", String(data?.id || ""));
      fm.append("firstname", String(data?.firstname || ""));
      fm.append("lastname", String(data?.lastname || ""));
      fm.append(
        "email",
        String(data?.email || profileEmail || "").toLowerCase()
      );
      fm.append("mobile", mobileDigits);
      if (altDigits) fm.append("alternateMobile", altDigits);
      if (data?.gender || gender) {
        fm.append("gender", String(data?.gender || gender));
      }

      for (const key in data) {
        if (skipUpdateKeys.has(key)) continue;
        if (
          [
            "id",
            "firstname",
            "lastname",
            "email",
            "mobile",
            "alternateMobile",
            "gender",
          ].includes(key)
        ) {
          continue;
        }
        if (key === "professional") {
          fm.append("professional", JSON.stringify(data[key] || {}));
        } else if (key === "industries_relation") {
          fm.append(
            "industries_relation",
            JSON.stringify(
              Array.isArray(industriesData) && industriesData.length
                ? industriesData
                : data[key] || []
            )
          );
        } else if (key === "education") {
          if (Array.isArray(data[key]) && data[key].length > 0) {
            fm.append("education", JSON.stringify(data[key]));
          }
        } else if (key === "experience") {
          if (Array.isArray(data[key]) && data[key].length > 0) {
            fm.append("experience", JSON.stringify(data[key]));
          }
        } else if (key === "status") {
          fm.append(key, "view");
        } else if (
          data[key] !== undefined &&
          data[key] !== null &&
          typeof data[key] !== "object"
        ) {
          fm.append(key, data[key]);
        } else if (data[key] instanceof File) {
          fm.append(key, data[key]);
        }
      }

      if (!fm.has("industries_relation")) {
        fm.append(
          "industries_relation",
          JSON.stringify(
            Array.isArray(industriesData) && industriesData.length
              ? industriesData
              : data?.industries_relation || []
          )
        );
      }
      if (!fm.has("professional")) {
        fm.append("professional", JSON.stringify(data?.professional || {}));
      }

      const result = await updateCandidateAPI({
        data: fm,
      });
      if (result?.error) {
        tostifyError(result.error);
        return;
      }
      if (result?.msg) {
        tostifySuccess("Data Update Successfully");
        setShowProfile(false);
        reloadMatches();
      } else {
        tostifyError(result?.constraint || "Update failed");
      }
    } catch (err) {
      tostifyError(err?.message || "Update failed");
    } finally {
      setProfileSaving(false);
    }
  };

  const viewProfileColumn = {
    name: "Profile",
    minWidth: "240px",
    cell: (row) => {
      const label = getViewProfileButtonLabel(row, viewedCandidateIds);
      const isViewAgain = label === "View Again";
      return (
        <div className="d-flex align-items-center flex-wrap" style={{ gap: 8 }}>
          <Button
            onClick={() => openViewProfile(row)}
            style={{
              padding: "10px",
              backgroundColor: isViewAgain ? `${themeColor}70` : themeColor,
              color: isViewAgain ? themeColor : "white",
              border: isViewAgain ? `1px solid ${themeColor}` : "none",
              fontWeight: isViewAgain ? "500" : "600",
            }}
            color="default"
          >
            {label}
          </Button>
          <Button
            onClick={() => openEditProfile(row)}
            style={{
              padding: "10px",
              backgroundColor: "transparent",
              color: themeColor,
              border: `1px solid ${themeColor || "#7367f0"}`,
              fontWeight: "600",
            }}
            color="default"
            title="Edit Profile"
          >
            Edit Profile
          </Button>
        </div>
      );
    },
  };

  const interviewScheduleColumn = {
    name: "Interview Shedule",
    minWidth: "150px",
    cell: (row) => (
      <Button
        onClick={() => openInterviewDialog(row)}
        style={{ padding: "10px", backgroundColor: themeColor, color: "white" }}
        color="default"
      >
        {getInterviewButtonLabel(row)}
      </Button>
    ),
  };

  const interviewStatusColumn = {
    name: "Interview Status",
    minWidth: "130px",
    cell: (row) => <InterviewStatusCell row={row} />,
  };

  const customStyles = {
    headCells: {
      style: {
        justifyContent: "center",
        backgroundColor: `${themeColor}10`,
      },
    },
    cells: {
      style: {
        justifyContent: "center",
        fontWeight: "bold",
      },
    },
  };

  const matchCandidateNameCell = (row) => {
    const name =
      [row?.firstname, row?.lastname].filter(Boolean).join(" ").trim() || "-";
    const showNew = shouldShowNewBestMatchBadge(
      row,
      jobOpeningRow,
      viewedCandidateIds
    );
    return (
      <div className="d-flex align-items-center flex-wrap" style={{ gap: 10 }}>
        <span
          style={{
            textDecoration: "underline",
            textUnderlineOffset: "2px",
            color: themeColor || "#323D76",
            cursor: "pointer",
          }}
          onClick={() => openViewProfile(row)}
          title="View Profile"
        >
          {name}
        </span>
        {showNew ? <NewBestMatchCandidateBadge themeColor={themeColor} /> : null}
      </div>
    );
  };

  const columnsClients = [
    {
      name: "Candidate",
      minWidth: "200px",
      cell: (row) => matchCandidateNameCell(row),
    },
    {
      name: "Match Score",
      selector: (row) =>
        row?.matchScore != null ? `${row.matchScore}%` : "0%",
      minWidth: "110px",
    },
    {
      name: "Profile Completion",
      selector: (row) =>
        row?.profileCompleteness != null
          ? `${row.profileCompleteness}%`
          : "-",
      minWidth: "120px",
    },
    {
      name: "Job Category",
      selector: (row) => row?.professional?.jobCategory?.jobCategory,
    },
    {
      name: "Qualification Held",
      selector: (row) => row?.professional?.highestQualification,
    },
    {
      name: "Experience",
      selector: (row) => row?.professional?.experienceInyear,
    },

    {
      name: "Currant Salary",
      selector: (row) => formatSalaryDisplay(row?.professional?.currentSalary),
    },
    {
      name: "Expected Salary",
      selector: (row) => formatSalaryDisplay(row?.professional?.expectedsalary),
    },
    {
      name: "Preferable Job Location",
      selector: (row) => row?.professional?.preferedJobLocation,
    },
    {
      name: "Notice Period",
      selector: (row) => row?.professional?.noticePeriod,
    },
    {
      name: "Currently Working",
      selector: (row) => row?.professional?.currentlyWorking,
    },
    {
      name: "City",
      selector: (row) => row?.city,
    },
    interviewStatusColumn,
    viewProfileColumn,
    interviewScheduleColumn,
  ];
  const subscriptionColumnsClients = [
    {
      name: "Candidate",
      minWidth: "200px",
      cell: (row) => matchCandidateNameCell(row),
    },
    {
      name: "Match Score",
      selector: (row) =>
        row?.matchScore != null ? `${row.matchScore}%` : "0%",
      minWidth: "110px",
    },
    {
      name: "Profile Completion",
      selector: (row) =>
        row?.profileCompleteness != null
          ? `${row.profileCompleteness}%`
          : "-",
      minWidth: "120px",
    },
    {
      name: "Email-id",
      selector: (row) => row?.email,
    },
    {
      name: "Contact number",
      selector: (row) => row?.mobile,
    },
    {
      name: "Job Category",
      selector: (row) => row?.professional?.jobCategory?.jobCategory,
    },
    {
      name: "Qualification Held",
      selector: (row) => row?.professional?.highestQualification,
    },
    {
      name: "Experience",
      selector: (row) => row?.professional?.experienceInyear,
    },
    {
      name: "Currant Salary",
      selector: (row) => formatSalaryDisplay(row?.professional?.currentSalary),
    },
    {
      name: "Expected Salary",
      selector: (row) => formatSalaryDisplay(row?.professional?.expectedsalary),
    },
    {
      name: "Preferable Job Location",
      selector: (row) => row?.professional?.preferedJobLocation,
    },
    {
      name: "Notice Period",
      selector: (row) => row?.professional?.noticePeriod,
    },
    {
      name: "Currently Working",
      selector: (row) => row?.professional?.currentlyWorking,
    },
    {
      name: "City",
      selector: (row) => row?.city,
    },
    interviewStatusColumn,
    viewProfileColumn,
    interviewScheduleColumn,
  ];

  const handlePerRowsChange = async (newPerPage, pageNum) => {
    setPerPage(newPerPage);
    getJobOpeningMatchCandidate(pageNum, newPerPage, sortBy, matchScore, matchDuration);
  };

  const handlePageChange = (pageNum) => {
    setPage(pageNum);
    getJobOpeningMatchCandidate(pageNum, perPage, sortBy, matchScore, matchDuration);
  };

  return (
    <>
      <div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            flexWrap: "wrap",
            gap: "8px",
            marginBottom: "12px",
          }}
        >
          <Button
            color="default"
            className="btn-icon"
            title="Job Details"
            aria-label="Job Details"
            style={{
              color: themeColor,
              border: `1px solid ${themeColor || "#7367f0"}`,
              padding: "6px 10px",
              display: "inline-flex",
              alignItems: "center",
              justifyContent: "center",
            }}
            onClick={() => setDetailsOpen((prev) => !prev)}
          >
            <Menu size={18} />
          </Button>
          {!embeddedMode && (
            <Button
              style={{
                color: themeColor,
                display: "flex",
                alignItems: "center",
                gap: "5px",
              }}
              className="add-new-user"
              color="default"
              onClick={() => {
                history.push(`/${slug}/jobopening`);
              }}
            >
              <ArrowLeft size={17} />
              Back
            </Button>
          )}
          <Button
            color="default"
            style={{
              backgroundColor:
                matchScore || matchDuration ? "#D97706" : themeColor,
              color: "white",
              width: "145px",
              marginLeft: "auto",
            }}
            onClick={() => setFilterToggleMode((prev) => !prev)}
          >
            Filter Data
          </Button>
        </div>
        <JobOpeningMatchFilters
          asSidebar
          open={filterToggleMode}
          toggleSidebar={() => setFilterToggleMode((prev) => !prev)}
          sortBy={sortBy}
          matchScore={matchScore}
          matchDuration={matchDuration}
          onSortChange={handleSortChange}
          onMatchScoreChange={handleMatchScoreChange}
          onMatchDurationChange={handleMatchDurationChange}
          onSearch={handleFilterSearch}
          onClear={handleFilterClear}
        />
        <Row>
          <Col sm={12} md={4} lg={4} xl={3} style={{ display: detailsOpen ? "block" : "none" }}>
            <Collapse isOpen={detailsOpen}>
            <Card>
              <CardBody>
                <h5
                  className="fw-bolder border-bottom pb-50 mb-1"
                  style={{ color: themeColor }}
                >
                  Job Description — Best Match
                </h5>
                <div
                  style={{
                    display: "flex",
                    flexDirection: "column",
                    gap: "1rem",
                  }}
                >
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-primary"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<MdOutlineCategory size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">Job Category</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {jobOpeningRow?.jobCategory?.jobCategory}
                        </small>
                      </div>
                    </div>
                  </div>
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-success"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<BsPersonWorkspace size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">No. Of Vacancy</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {jobOpeningRow.numberOfVacancy}
                        </small>
                      </div>
                    </div>
                  </div>
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-danger"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<MdOutlineWorkHistory size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">Experience</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {jobOpeningRow.minExperienceYears}
                        </small>
                      </div>
                    </div>
                  </div>
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-warning"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<BsGenderAmbiguous size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">Gender</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {jobOpeningRow.gender}
                        </small>
                      </div>
                    </div>
                  </div>
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-info"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<MdOutlinePlace size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">Work</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {jobOpeningRow.workType}
                        </small>
                      </div>
                    </div>
                  </div>
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-primary"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<PiStudentLight size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">Qualification</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {jobOpeningRow.qualification}
                        </small>
                      </div>
                    </div>
                  </div>
                  <div key={"item.title"} className="transaction-item">
                    <div className="d-flex gap-1">
                      <Avatar
                        className="rounded"
                        color={"light-success"}
                        contentStyles={{ width: "44px", height: "44px" }}
                        icon={<MdOutlineAttachMoney size={18} />}
                      />
                      <div>
                        <h6 className="transaction-title">Salary range</h6>
                        <small style={{ fontWeight: "400" }}>
                          {" "}
                          {`${jobOpeningRow.salaryRangeStart} to ${jobOpeningRow.salaryRangeEnd}`}
                        </small>
                      </div>
                    </div>
                  </div>
                </div>
              </CardBody>
            </Card>
            </Collapse>
          </Col>
          <Col sm={12} md={detailsOpen ? 8 : 12} lg={detailsOpen ? 8 : 12} xl={detailsOpen ? 9 : 12}>
            <Card>
              {!embeddedMode && (
                <CardBody className="pb-0">
                  <h5
                    style={{
                      color: themeColor,
                      fontWeight: "600",
                      margin: "0 0 8px 0",
                    }}
                  >
                    Best Matches Candidates
                  </h5>
                </CardBody>
              )}
              <div className="react-dataTable job-opening-match-table">
                <DataTable
                  paginationRowsPerPageOptions={[10, 20, 30, 50, 100]}
                  selectableRows={false}
                  fixedHeader={true}
                  progressPending={showTableLoader}
                  progressComponent={
                    <ComponentSpinner
                      isClientCandidate={true}
                      theamcolour={themeColor}
                    />
                  }
                  noDataComponent={
                    showTableLoader ? (
                      <ComponentSpinner
                        isClientCandidate={true}
                        theamcolour={themeColor}
                      />
                    ) : (
                      <div style={{ padding: "24px", color: "#6e6b7b" }}>
                        No candidates found
                      </div>
                    )
                  }
                  fixedHeaderScrollHeight="500px"
                  noHeader
                  sortServer
                  pagination
                  responsive
                  onChangeRowsPerPage={handlePerRowsChange}
                  onChangePage={handlePageChange}
                  paginationTotalRows={jobOpeningMatchCandidate?.total || 0}
                  paginationServer
                  allowRowEvents
                  customStyles={customStyles}
                  highlightOnHover={true}
                  columns={
                    user?.clients?.id
                      ? user?.subscription?.plan?.planName == "free" ||
                        user?.subscription?.plan?.planName == "Trial"
                        ? columnsClients
                        : subscriptionColumnsClients
                      : columnsClients
                  }
                  className="react-dataTable"
                  data={
                    showTableLoader
                      ? []
                      : jobOpeningMatchCandidate?.results || []
                  }
                />
              </div>
            </Card>
          </Col>
        </Row>
      </div>
      <Modal className="modal-dialog-centered" isOpen={resumeCountFinishError}>
        <ModalHeader
          toggle={() => {
            dispatch({
              type: subscriptionActions.RESUME_COUNT_FINISH,
              payload: false,
            });
          }}
        />
        <ModalBody>
          You Can't Download Resume More Than 5, Please Upgrade Your Plan!!
          {/* <br />
          Contact :{` ${user?.agency?.phoneNumber}`} */}
        </ModalBody>
        <ModalFooter>
          <Button
            color="link"
            onClick={() => {
              dispatch({
                type: subscriptionActions.RESUME_COUNT_FINISH,
                payload: false,
              });
            }}
          >
            Close
          </Button>
          <Button
            color="default"
            style={{ backgroundColor: themeColor, color: "white" }}
            onClick={() => {
              dispatch({
                type: subscriptionActions.RESUME_COUNT_FINISH,
                payload: false,
              });
              history.push(`${slug}/pricing`);
            }}
          >
            Upgrade Plan
          </Button>
        </ModalFooter>
      </Modal>
      {showInterview ? (
        <InterviewDialog
          loading={interviewLoading}
          setCreate={setCreateInterview}
          create={createInterview}
          setUpdate={setUpdateInterview}
          interviewHandler={interviewHandler}
          interview={interview}
          setInterview={setInterview}
          show={showInterview}
          setShow={setShowInterview}
          clients={clients}
          candidates={candidates}
          update={updateInterview}
          loginUser={loginUser}
          setSelectCandidateValidation={setSelectCandidateValidation}
          setSelectCompanyValidation={setSelectCompanyValidation}
          setDateValidation={setDateValidation}
          setInterviewStartValidation={setInterviewStartValidation}
          setInterviewValidation={setInterviewValidation}
        />
      ) : null}
      <JobMatchProfileDialog
        show={showProfile}
        setShow={setShowProfile}
        candidate={profileCandidate}
        setCandidate={setProfileCandidate}
        industriesData={industriesData}
        setIndustriesData={setIndustriesData}
        gender={gender}
        setGender={setGender}
        setEmail={setProfileEmail}
        isDisabledAllFields={profileReadOnly}
        setIsDisabledAllFields={setProfileReadOnly}
        CandidateHandler={handleProfileSave}
        loading={profileSaving}
      />
    </>
  );
};

export default JobOpeningMatches;
